const GM_NATURE_AUDIO = "data:audio/mpeg;base64,";
function gmHtml(s){ return s.replaceAll("__GM_NATURE_AUDIO__", GM_NATURE_AUDIO); }

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    const headers = {
      "Content-Type": "text/html; charset=UTF-8",
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "strict-origin-when-cross-origin"
    };
    if (request.method === "OPTIONS") return new Response(null, {status:204, headers:{"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"GET,HEAD,OPTIONS","Access-Control-Allow-Headers":"*"}});
    // Same-origin API bridge: keeps the customer/admin UI on one origin and avoids browser CORS/network failures.
    if (path === '/api' || path.startsWith('/api/')) {
      const backend = 'https://green-moon-products.greenmoon-eg.workers.dev' + path + url.search;
      try {
        const upstream = await fetch(new Request(backend, request));
        const h = new Headers(upstream.headers);
        h.set('Cache-Control','no-store');
        h.set('Access-Control-Allow-Origin','*');
        h.set('Access-Control-Allow-Methods','GET,POST,PUT,DELETE,OPTIONS');
        h.set('Access-Control-Allow-Headers','Content-Type,x-admin-token');
        return new Response(upstream.body,{status:upstream.status,statusText:upstream.statusText,headers:h});
      } catch (e) {
        return new Response(JSON.stringify({error:'تعذر الاتصال بخدمة المتجر',detail:String(e?.message||e)}),{status:502,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','access-control-allow-origin':'*'}});
      }
    }
    if (path.startsWith('/assets/')) {
      const file = path.slice('/assets/'.length);
      const allowed = /^[A-Za-z0-9._-]+$/.test(file);
      if (!allowed) return new Response('Not found', {status:404});
      const urls = [
        'https://raw.githubusercontent.com/mohammedelgarhy90-rgb/green-moon-products/main/' + encodeURIComponent(file),
        'https://raw.githubusercontent.com/mohammedelgarhy90-rgb/green-moon-products/main/assets/' + encodeURIComponent(file)
      ];
      let r = null;
      for (const u of urls) {
        try {
          const x = await fetch(u, {cf:{cacheTtl:86400,cacheEverything:true}});
          if (x.ok) { r = x; break; }
        } catch (_) {}
      }
      if (!r) {
        const fallback = file === 'doctor-icon.png' ? 'logo.png' : (file === 'doctor-hero.png' ? 'hero.png' : null);
        if (fallback) {
          try {
            const fu = 'https://raw.githubusercontent.com/mohammedelgarhy90-rgb/green-moon-products/main/' + fallback;
            const fx = await fetch(fu, {cf:{cacheTtl:86400,cacheEverything:true}});
            if (fx.ok) r = fx;
          } catch (_) {}
        }
      }
      if (!r) return new Response('Asset not found', {status:404});
      const h = new Headers(r.headers); h.set('Cache-Control','public, max-age=86400');
      return new Response(r.body,{status:r.status,headers:h});
    }
    if (path === '/admin' || path === '/admin/') return new Response(gmHtml(ADMIN_HTML),{headers});
    if (/^\/product\/(?:\d+)(?:\/)?$/.test(path) || path === '/product/11.html') return new Response(gmHtml(PRODUCT_HTML),{headers});
    if (path === '/favicon.ico') return new Response('',{status:204});
    return new Response(gmHtml(SITE_HTML),{headers});
  }
};

